-- Passo a passo em português para os exercícios do catálogo que só tinham o
-- texto original em inglês (`instructions`, que continua guardado). Preenche
-- `execution` apenas onde está vazio: nada já traduzido é sobrescrito.
update public.exercises set execution = array['Deite no chão com os pés presos e os joelhos flexionados.', 'Mãos atrás ou ao lado da cabeça, costas apoiadas no chão.', 'Flexione o quadril e a coluna, levando o tronco em direção aos joelhos até ficar perpendicular ao chão.', 'Desça só três quartos do caminho e repita.'] where id = 'b6ca8854-f8a3-47a1-9235-a95ec6f472b0' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com uma perna estendida no chão.', 'Flexione o quadril e o joelho da outra perna a 90°, apoiando com as mãos se precisar.', 'Estenda essa perna para cima, pausando brevemente no alto.', 'Volte à posição inicial; faça 10 a 20 repetições e troque de perna.'] where id = 'ebeca8db-faeb-46c5-91e4-012a2070ef3b' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Escolha uma carga leve e sente na máquina, com os pés sob os apoios e as mãos nas alças superiores.', 'Braços flexionados a 90°, com os tríceps apoiados.', 'Expirando, eleve as pernas enquanto contrai o tronco superior para baixo, em movimento lento e controlado.', 'Pause um segundo e volte devagar inspirando, sem usar as pernas para empurrar.'] where id = '10952731-e5d0-4bf1-8017-d6f31b28d036' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajoelhe no chão segurando o rolinho com as duas mãos à frente, apoiado no chão.', 'Inspirando, role devagar para frente, estendendo o corpo o máximo que conseguir sem encostar no chão.', 'Pause na posição esticada.', 'Expirando, puxe de volta até a posição inicial, com o abdômen sempre contraído.'] where id = '85e8e626-6ba0-463b-956b-3d85696782cc' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique em posição de flexão, segurando uma barra olímpica leve (2 a 5 kg de cada lado) no chão.', 'Com uma leve curvatura nas costas, eleve o quadril e role a barra em direção aos pés, expirando.', 'Mantenha o abdômen firme e os braços perpendiculares ao chão durante todo o movimento.', 'Após uma contração no alto, role a barra de volta devagar, inspirando.'] where id = '209eb4e5-673a-4b8e-b412-41294e3bac75' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite sobre a bola suíça com a lombar apoiada na curva da bola e os pés firmes no chão.', 'Braços ao lado do corpo ou cruzados no peito, sem puxar o pescoço.', 'Com o quadril parado, contraia o abdômen e enrole ombros e tronco para cima, expirando.', 'Segure a contração por um segundo e volte inspirando; a lombar não sai da bola.'] where id = '6baf8bfb-0f52-4ea5-9a75-be0c1d0b271c' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os joelhos flexionados a 90°, pés no chão ou num banco.', 'Segure um peso junto ao peito ou estendido acima do tronco.', 'Expirando, tire os ombros cerca de 10 cm do chão, mantendo a lombar apoiada.', 'Contraia o abdômen no alto, pause e desça devagar inspirando.'] where id = '540cf4c9-594e-40e9-956d-2b51775357e1' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite no chão com os pés presos e os joelhos flexionados.', 'Mãos atrás da cabeça, dedos entrelaçados.', 'Expirando, suba o tronco até formar um V com as coxas.', 'Segure a contração por um segundo e desça inspirando.'] where id = 'babf106c-d27d-4a86-8a8a-77a3ad483324' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda os elásticos na base do banco declinado, com as alças ao alcance quando deitado.', 'Prenda as pernas no banco e segure as alças junto à clavícula, palmas voltadas para o tronco.', 'Expirando, suba o tronco até ficar perpendicular ao chão, com os braços parados.', 'Segure por um segundo e desça inspirando.'] where id = '0c11fd29-2715-46cc-ab71-6fd18332678a' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajoelhe a uns 30 a 60 cm da polia alta com a corda presa.', 'Segure a corda com as duas mãos acima da cabeça, tronco ereto.', 'Flexione a coluna, levando as costelas em direção às pernas enquanto puxa a corda para baixo.', 'Pause embaixo e volte devagar; dá para fazer com rotação para trabalhar os oblíquos.'] where id = 'f0862d73-777f-4ec2-bc60-bdb3b059c291' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda as pernas no fim do banco declinado e deite.', 'Mãos levemente ao lado da cabeça, cotovelos para dentro, sem entrelaçar os dedos.', 'Pressionando a lombar contra o banco, tire os ombros cerca de 10 cm, expirando.', 'Contraia forte no alto por um segundo e desça devagar, sem usar impulso.'] where id = '999724fa-954d-4b92-9b3c-61489c88f7d1' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas no banco declinado, segurando o topo do banco com as duas mãos.', 'Pernas estendidas e paralelas ao chão, joelhos levemente flexionados.', 'Expirando, leve as pernas em direção ao tronco, enrolando a pelve e tirando o quadril do banco.', 'Segure um segundo com os joelhos perto do peito e volte inspirando.'] where id = 'd1e889c6-e34c-4643-bea1-bfe4b46cd338' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda a corda na polia alta e fique de costas para o aparelho.', 'Segure a corda sobre os ombros, junto ao peito.', 'Flexione a coluna, contraindo o abdômen para baixo o máximo que puder.', 'Segure a contração um instante e volte à posição inicial.'] where id = '34e99161-1c8d-4a47-a3d2-587f29562025' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os joelhos flexionados a cerca de 60° e os pés no chão.', 'Estenda os braços acima da cabeça, palmas cruzadas.', 'Expirando, enrole o tronco à frente tirando as escápulas do chão, com os braços alinhados à cabeça.', 'Segure um segundo e desça devagar inspirando.'] where id = 'e2d97c5f-70d8-4574-97a7-9952eede9780' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite com as pernas estendidas e os braços ao lado do corpo, palmas no chão.', 'Eleve as pernas até as coxas ficarem perpendiculares ao chão, pés juntos.', 'Leve as pernas em direção ao tronco, enrolando a pelve e tirando o quadril do chão.', 'Segure um segundo com os joelhos no peito e volte devagar.'] where id = 'e98f12e8-8e02-4811-ab69-c40a736dda16' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda a tornozeleira na polia baixa e deite num colchonete com os pés voltados para ela.', 'Eleve as pernas com os joelhos a 90°, alinhadas com o cabo.', 'Com as mãos atrás da cabeça, traga os joelhos para o tronco e tire o quadril do chão.', 'Pause e desça o quadril de forma lenta, mantendo tensão no abdômen.'] where id = '1c3281a4-cb0e-4212-8adb-f903647818b7' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajoelhe sob a polia alta com a corda e segure-a com as mãos ao lado do rosto.', 'Flexione levemente o quadril, deixando o peso estender a lombar.', 'Com o quadril parado, flexione a cintura levando os cotovelos ao meio das coxas, expirando.', 'Segure um segundo e volte devagar; não use carga a ponto de a lombar fazer o trabalho.'] where id = '4a124fb0-c399-4b2a-916b-eedfe6d45654' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda a corda na polia alta, ajoelhe a uns 60 cm do aparelho e segure a corda atrás da cabeça.', 'Contraia o abdômen e puxe para baixo até os cotovelos chegarem aos joelhos; suba devagar.', 'Na repetição seguinte, a partir da metade do caminho, gire um cotovelo em direção ao joelho oposto.', 'Alterne os lados a cada repetição, sempre de forma controlada.'] where id = 'e0527314-a5aa-483e-ac0f-399681a6c10e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os pés sobre a bola suíça e os joelhos a 90°.', 'Mãos levemente ao lado da cabeça, sem entrelaçar os dedos; lombar pressionada no chão.', 'Expirando, tire os ombros cerca de 10 cm do chão.', 'Contraia forte por um segundo e desça devagar, sem usar impulso.'] where id = '2fc7c1ad-94a9-4b75-b609-a9ae0b8b5352' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente no banco de costas para a polia alta, segurando a corda sobre os ombros.', 'Deixe o peso estender levemente a lombar.', 'Com o quadril parado, flexione a cintura levando os cotovelos em direção ao quadril, expirando.', 'Volte devagar inspirando.'] where id = '5b2c6c37-6257-4784-9010-1675b7555173' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajuste as alças do suspensório a uns 30 cm do chão.', 'Em prancha, de costas para o suporte, encaixe os pés nas alças, sem deixar o quadril cair.', 'Flexione joelhos e quadril, trazendo os joelhos para o tronco e enrolando a pelve.', 'Volte de forma controlada à posição inicial.'] where id = '32c06fad-eb6c-4784-8686-24c59b104bf0' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de bruços com uma perna sobre o rolo de liberação.', 'Gire a perna para o rolo ficar na parte interna da coxa.', 'Role entre o quadril e o joelho, segurando 10 a 30 segundos nos pontos de tensão.', 'Repita com a outra perna.'] where id = '9b4a8465-d671-4cda-9db6-3567526951ed' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os pés para o alto, um parceiro segurando os tornozelos.', 'Afaste as pernas o máximo que puder.', 'Tente fechar as pernas por 10 segundos ou mais enquanto o parceiro impede.', 'Relaxe e deixe o parceiro afastar seus pés até um alongamento confortável, avisando quando for o bastante.'] where id = '6091a8a3-4922-4a34-a116-7f1ec80c035e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Leve um kettlebell acima da cabeça com um braço, cotovelo travado.', 'Pés virados a 45° para o lado oposto, braço livre atrás das costas.', 'Mantendo o kettlebell travado, empurre o quadril para o lado dele e desça o tronco o máximo possível.', 'Pause e volte à posição inicial.'] where id = '2437fea3-044e-4de6-b548-f7185c4cb491' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique em pé com os pés na largura dos ombros, mãos atrás da cabeça se quiser.', 'Flexione joelhos e quadril, sentando para trás.', 'Desça até onde conseguir com boa postura, cabeça e peito erguidos e joelhos para fora.', 'Volte rápido à posição inicial.'] where id = 'd5f009f2-4316-4859-b01e-54ed73766372' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajuste a barra no rack na altura certa e ajoelhe atrás dela (um colchonete protege os joelhos).', 'Apoie a barra nas costas, com as escápulas retraídas, e tire-a do rack.', 'Olhando à frente, sente o quadril para trás até encostar nas panturrilhas.', 'Volte o tronco à posição ereta.'] where id = '4d3b35c3-60ac-4cef-8005-1b1d9696e473' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['No rack, apoie a barra atrás dos ombros e tire-a do suporte estendendo as pernas.', 'Afaste-se e posicione os pés mais abertos que os ombros, pontas levemente para fora.', 'Com a cabeça erguida e as costas retas, desça flexionando os joelhos até as coxas passarem um pouco da paralela, inspirando.', 'Mantenha os joelhos alinhados com os pés e suba empurrando o chão com os calcanhares, expirando.'] where id = 'ebe29b03-f1bf-43a0-ba69-712ed2ca969a' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, com a barra atrás dos ombros e os pés bem afastados, o pé da frente virado para o lado.', 'Desça para o lado do pé virado, flexionando joelho e quadril dessa perna, com a outra quase estendida, inspirando.', 'Volte estendendo quadril e joelho, expirando.', 'Faça as repetições e troque de lado.'] where id = 'c960d02c-d0bd-43a5-91ca-ed4c55164ad9' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajuste as alças do suspensório a 45–75 cm do chão e apoie o pé de trás numa delas.', 'Olhe à frente, peito erguido, joelho da frente levemente flexionado.', 'Desça flexionando joelho e quadril, com o peso no calcanhar da frente.', 'Volte estendendo quadril e joelho.'] where id = '9d473794-8d13-47dc-9c9a-27e194434e30' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Coloque um banco a 60–90 cm atrás do Smith e apoie a barra atrás dos ombros.', 'Um pé à frente, sob a barra, e o peito do outro pé apoiado no banco.', 'Desça flexionando o joelho da frente até a coxa passar um pouco da paralela, sem o joelho passar da ponta do pé.', 'Suba empurrando com o calcanhar; complete as repetições e troque de perna.'] where id = 'f3993acf-a224-426b-a3bc-9da38a59021a' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda as correntes na barra de modo que alguns elos fiquem no chão no alto do movimento.', 'Apoie a barra atrás dos ombros, escápulas juntas, e tire-a do rack.', 'Pés afastados, cabeça à frente: sente o quadril para trás e desça até passar da paralela.', 'Com o peso nos calcanhares e os joelhos para fora, suba mantendo o corpo firme.'] where id = '56d56e07-1323-448d-9458-64b6fc879315' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda os elásticos nas pontas da barra, com tensão adequada.', 'Apoie a barra atrás dos ombros, escápulas juntas, e tire-a do rack.', 'Pés afastados, cabeça à frente: sente o quadril para trás e desça até passar da paralela.', 'Com o peso nos calcanhares e os joelhos para fora, suba mantendo o corpo firme.'] where id = 'adf8ab24-af98-4ff2-abfe-4fcaa8d24342' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, com um halter em cada mão ao lado das pernas e os pés na largura dos ombros.', 'Cabeça erguida e costas retas.', 'Desça flexionando os joelhos até as coxas ficarem paralelas ao chão, sem os joelhos passarem das pontas dos pés.', 'Suba empurrando o chão com os calcanhares, expirando.'] where id = 'a08a53ac-ddbd-454e-9f09-adbdcc2a716d' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique em pé sobre dois bancos com o cinto de peso na cintura e o peso pendurado entre as pernas.', 'Pontas dos pés para fora, braços estendidos ao lado do corpo.', 'Desça flexionando os joelhos até passar um pouco da paralela, cabeça erguida, inspirando.', 'Suba estendendo as pernas, expirando.'] where id = '1822da3f-3334-4157-b4db-c7c4bf0f564b' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajoelhe com a barra atrás dos ombros (ou sem peso), de preferência dentro do rack.', 'Sente o quadril para trás até os glúteos tocarem os pés, peito erguido.', 'Exploda com o quadril para cair com os pés no chão.', 'Complete o agachamento e fique em pé empurrando com os calcanhares.'] where id = '87420827-b1dc-49f9-9f3e-c862a1a1653c' and coalesce(cardinality(execution), 0) = 0;
