update public.exercises set execution = array['No rack, com um banco atrás de você, apoie a barra sobre os deltoides com os braços cruzados.', 'Tire a barra do suporte e posicione os pés na largura dos ombros, costas retas.', 'Desça flexionando os joelhos até encostar os glúteos no banco, inspirando.', 'Suba empurrando com os calcanhares, sem os joelhos passarem das pontas dos pés.'] where id = 'b438fa8a-dc31-46a8-9f18-9efc6c043c4a' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Segure um kettlebell leve pelas alças, junto ao peito.', 'Agache entre as pernas até os posteriores tocarem as panturrilhas, peito e cabeça erguidos.', 'Embaixo, pause e use os cotovelos para empurrar os joelhos para fora.', 'Volte e repita de 10 a 20 vezes.'] where id = 'd417c2a8-dd37-4e6c-9175-0568f714535d' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Apoie as costas no encosto e os ombros sob as almofadas do hack.', 'Pés na plataforma na largura dos ombros, pontas levemente para fora; solte as travas.', 'Desça flexionando os joelhos até passar um pouco da paralela, costas no encosto, inspirando.', 'Suba empurrando com os calcanhares, sem travar os joelhos.'] where id = '1c98711f-6e2d-4afc-b2ab-7aaf3935203e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, segure a barra atrás do corpo com os braços estendidos, pés na largura dos ombros.', 'Cabeça erguida e costas retas.', 'Agache até as coxas ficarem paralelas ao chão, inspirando.', 'Suba empurrando com os calcanhares, expirando.'] where id = 'a41b7517-2fcb-4d7f-8b5c-ed4df50ea3ce' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['No rack, com uma caixa atrás de você, prenda os elásticos acima da barra.', 'Apoie a barra atrás dos ombros e tire-a do suporte.', 'Desça sentando o quadril para trás até sentar na caixa, sem quicar; relaxe por um instante.', 'Suba com o peso nos calcanhares e os joelhos para fora; devolva a barra ao rack com cuidado.'] where id = '87c704c8-28f4-424b-9e22-15e1f4ff85cc' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Com a barra apoiada na frente dos ombros, pés sob o quadril.', 'Flexione um pouco os joelhos e inverta com o máximo de força, empurrando com os calcanhares.', 'Assim que os pés saírem do chão, receba a barra num agachamento completo com os braços estendidos acima da cabeça.', 'Fique em pé mantendo a barra sobre os calcanhares e devolva a carga ao chão com cuidado.'] where id = '5051aab3-a790-40e1-8c42-d75bad54faec' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Apoie a barra atrás dos ombros e tire-a do rack.', 'Dê um passo à frente, ficando uns 45 cm à frente da barra, pés na largura dos ombros.', 'Desça flexionando os joelhos até passar de 90°, olhando à frente.', 'Suba empurrando o chão com os calcanhares, expirando.'] where id = '2d6db8d1-5be7-4656-8f75-3c132ee68306' and coalesce(cardinality(execution), 0) = 0;
