update public.exercises set execution = array['No rack, com a caixa atrás e as correntes presas na barra (alguns elos no chão no alto).', 'Apoie a barra atrás dos ombros e tire-a do suporte.', 'Sente o quadril para trás até ficar sentado na caixa; pause sem quicar.', 'Com o peso nos calcanhares e os joelhos para fora, suba de forma explosiva.'] where id = '5d93929c-1500-488e-936d-4e7fe57a3a64' and coalesce(cardinality(execution), 0) = 0;
