update public.exercises set execution = array['Fique de quatro apoios.', 'Eleve uma perna e segure o pé ou o tornozelo com a mão, joelho bem flexionado.', 'Empurre o quadril em direção ao chão para alongar quadríceps e flexores do quadril.', 'Segure 10 a 20 segundos e troque de lado.'] where id = 'bd7b2c70-dd21-4af4-9254-499f6c9805c3' and coalesce(cardinality(execution), 0) = 0;
