update public.exercises set execution = array['Segure a barra com pegada aberta, na altura do meio das coxas.', 'Costas retas e levemente inclinadas à frente.', 'Encolha os ombros em direção às orelhas.', 'Não use carga a ponto de deixar o movimento lento.'] where id = '1dc9d3ed-8a31-4db7-b02d-ced3a7264925' and coalesce(cardinality(execution), 0) = 0;
