update public.exercises set execution = array['Deite de lado sobre a bola suíça, com o lado esquerdo do tronco apoiado e os pés no chão.', 'Segure uma anilha com a mão direita junto ao lado direito da cabeça; mão esquerda sobre os oblíquos.', 'Expirando, eleve o tronco inclinando a cintura para o lado.', 'Segure um segundo, desça inspirando; complete e troque de lado.'] where id = 'ce660505-0c1a-491b-ad71-cf8d4a723b84' and coalesce(cardinality(execution), 0) = 0;
