update public.exercises set execution = array['Em pé, com a barra atrás dos ombros e os pés na largura dos ombros.', 'Com as costas retas e a cabeça erguida, incline-se só pela cintura para a direita, inspirando.', 'Segure um segundo e volte expirando, sem mexer o resto do corpo.', 'Repita para a esquerda e alterne.'] where id = 'fc855797-76b8-4e66-b8b4-9cd370ae6e10' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, com um halter na mão esquerda e a mão direita na cintura, pés na largura dos ombros.', 'Incline-se só pela cintura para a direita o máximo possível, inspirando.', 'Segure um segundo e volte expirando; depois incline para a esquerda.', 'Complete as repetições e troque o halter de mão.'] where id = 'a9aa76cc-284e-4532-afad-303068d580a4' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os braços ao lado do corpo, joelhos a uns 75° e pés a 5 cm do chão.', 'Com o abdômen inferior, traga os joelhos em sua direção mantendo o ângulo.', 'Continue até tirar o quadril do chão, enrolando a pelve, expirando.', 'Contraia por um segundo e volte devagar.'] where id = '7b2b9637-8611-4c5e-beb3-ef53a0e16e13' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com os joelhos flexionados e as solas dos pés juntas; um parceiro segura seus joelhos.', 'Tente fechar os joelhos por 10 a 20 segundos enquanto o parceiro impede.', 'Relaxe e deixe o parceiro empurrar os joelhos com cuidado em direção ao chão.', 'Avise quando o alongamento for suficiente.'] where id = '4d15052f-02b5-4444-8b58-9211e30a6ae8' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Leve o kettlebell ao ombro estendendo pernas e quadril.', 'Incline-se para o lado oposto ao kettlebell até tocar o chão com a mão livre, olhando para o peso.', 'Enquanto inclina, empurre o kettlebell para cima, braço perpendicular ao chão.', 'Volte à posição ereta com o peso acima da cabeça e retorne-o ao ombro.'] where id = '16bb2e88-b8a2-4b1b-8b61-7d3145af2347' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, entrelace as mãos atrás das costas com as palmas juntas.', 'Estenda os braços e gire-os para as palmas ficarem voltadas para baixo.', 'Eleve os braços.', 'Segure ao sentir o alongamento no bíceps.'] where id = '6637007d-4fd5-4e99-9bba-351ae2057698' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente no chão com os joelhos flexionados e um parceiro em pé atrás de você.', 'Estenda os braços para trás, palmas frente a frente; o parceiro segura seus punhos.', 'Tente flexionar os cotovelos por 10 a 20 segundos enquanto o parceiro impede.', 'Relaxe e deixe o parceiro elevar seus punhos com cuidado; avise quando bastar.'] where id = 'fd204e10-41e1-4d12-aa4e-483fbfbcab97' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na bicicleta e ajuste o banco à sua altura.', 'Pedale num ritmo constante, mantendo a postura.', 'Ajuste a intensidade conforme o objetivo do treino.'] where id = 'a37757c9-c9de-40b9-bdf4-16161a72a52e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na bicicleta ergométrica e ajuste o banco à sua altura.', 'Escolha o modo manual ou um programa; alguns aparelhos pedem idade e peso para estimar as calorias.', 'Ajuste a resistência ao longo do treino.', 'Use os sensores das alças para acompanhar a frequência cardíaca, se houver.'] where id = '544bee6c-55cc-4a7b-925e-85e4bd205311' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite no banco com uma a cinco tábuas sobre o peito, presas por um parceiro, elásticos ou sob a camiseta.', 'Arqueie as costas, junte as escápulas e firme os pés.', 'Tire a barra do suporte com pegada na largura dos ombros, mantendo barra, punhos e cotovelos alinhados.', 'Desça até as tábuas e empurre com força, cotovelos fechados até estender.'] where id = '8f3da730-37ad-4348-bb1c-d266593ed275' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na beirada de uma cadeira segurando o encosto atrás de você.', 'Estenda os braços com as costas retas.', 'Leve o tronco à frente até sentir o alongamento.', 'Segure 20 a 30 segundos.'] where id = '58185a9f-5bf6-48dd-b545-514c4c500b71' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Coloque a barra no rack na altura do peito e segure-a na largura dos ombros.', 'Dê um ou dois passos para trás, pés juntos, apoiando-se na barra com os braços estendidos.', 'Flexione os cotovelos, aproximando o corpo da barra.', 'Pause e estenda os cotovelos; para progredir, use correntes sobre os ombros.'] where id = '021b8d37-1972-4ee4-b0f1-070a20cc5a71' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique em prancha, apoiado nos antebraços (na largura dos ombros) e nas pontas dos pés.', 'Pressione as palmas no chão e estenda os cotovelos, elevando o corpo.', 'Mantenha o tronco rígido durante o movimento.', 'Volte devagar aos antebraços e repita.'] where id = 'b8e3e173-18cc-4ced-8114-f37df78c5b56' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Apoie a barra atrás dos ombros (não em cima) e tire-a do rack.', 'Costas firmes, escápulas juntas e joelhos levemente flexionados.', 'Incline o tronco à frente levando o quadril para trás, até quase a paralela, com as costas arqueadas.', 'Volte estendendo o quadril com glúteos e posteriores.'] where id = '99406fd4-eb7a-447e-8236-e01ede0c38e5' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda o elástico num poste e passe a outra ponta atrás do pescoço, um pouco afastado.', 'Flexione o quadril levando o glúteo o mais para trás possível.', 'Com as costas retas e os joelhos levemente flexionados, incline até uns 90°.', 'Volte empurrando o quadril à frente até ficar em pé.'] where id = '97a82d38-eb89-4cc6-a927-a02b8c4e9ce7' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Pise numa ponta do elástico com os pés levemente afastados.', 'Incline-se e passe a outra ponta atrás do pescoço.', 'Com as pernas estendidas, estenda o quadril até quase ficar em pé.', 'Volte à posição inicial sem arredondar as costas.'] where id = 'd0929038-d2ba-4b83-b6ca-a8e7d199ba29' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajuste a barra nos pinos na altura do abdômen.', 'Incline-se sob a barra e apoie-a atrás dos ombros, quase paralelo ao chão, costas firmes e joelhos levemente flexionados.', 'Estenda o quadril com glúteos e posteriores até ficar em pé com a carga.', 'Desça devagar até apoiar a barra de novo nos pinos.'] where id = '9935dc9b-3a27-42f4-9810-bc707a5eacc5' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda uma alça em cada lado do cross, na posição mais baixa, e coloque o bosu à frente e no centro.', 'Deite com a lombar arqueada sobre o bosu e segure as alças, braços estendidos à frente entre os joelhos.', 'Eleve o tronco num abdominal sem dobrar os braços e desça devagar.', 'Ao chegar à falha, faça inclinações laterais alternadas levando as mãos aos calcanhares para os oblíquos.'] where id = '7b156f22-7756-4b0e-8872-9df31ed152b9' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de costas com as pernas estendidas e os braços ao lado do corpo.', 'Traga os joelhos ao peito flexionando quadril e joelhos.', 'Estenda as pernas para cima, perpendiculares ao chão, e eleve a pelve tirando os glúteos do chão.', 'Pause e volte à posição inicial.'] where id = 'fe7ffb47-5efa-4068-ba35-274cca242d07' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, segure um kettlebell com uma mão.', 'Balance o kettlebell para trás com força e inverta o movimento.', 'Aperte a alça com força e leve o kettlebell ao ombro de cabeça para baixo (fundo para cima).', 'Mantenha o controle na posição alta.'] where id = 'be92b972-59fa-4b22-98ba-08c9c7352123' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de lado com o braço sobre o rolo, a parte externa do bíceps apoiada nele.', 'Eleve o quadril, apoiando o peso no braço e nos pés.', 'Segure 10 a 30 segundos.', 'Troque de lado.'] where id = '15528cd4-bcae-4e72-b4c4-4a0599b091ab' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, estenda os braços para os lados, paralelos ao chão.', 'Faça círculos de uns 30 cm de diâmetro com os braços estendidos, respirando normalmente.', 'Continue por cerca de 10 segundos.', 'Inverta o sentido dos círculos.'] where id = 'aca854e5-35ef-4262-8be3-cc85686e2b48' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Segure os halteres à frente das coxas, palmas voltadas para elas, cotovelos levemente flexionados e firmes.', 'Expirando, eleve os halteres em semicírculo até acima da cabeça.', 'Volte devagar pelo mesmo caminho, inspirando.', 'Repita.'] where id = '4b4ec704-e1fd-478f-b51b-5646154de733' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Segure a barra larga da polia alta com pegada pronada mais aberta que os ombros e dê uns passos para trás.', 'Incline o tronco uns 30° à frente com os braços estendidos e cotovelos levemente flexionados.', 'Com os braços retos, puxe a barra até as laterais das coxas contraindo as costas, expirando.', 'Volte à posição inicial com os braços retos, inspirando.'] where id = '3df0d016-74bf-4adc-9702-c2665d77ad45' and coalesce(cardinality(execution), 0) = 0;
