update public.exercises set execution = array['Ajoelhe com o pé esquerdo à frente e o joelho direito no chão, pressionando o calcanhar da frente.', 'Balance os braços como pêndulos longos.', 'Feche o ângulo dos braços como numa corrida leve, depois corrida e sprint, acelerando as mãos à frente ao passarem do quadril.', 'Troque o joelho e repita.'] where id = 'b6a38573-ed7f-41d9-b715-3d6619edadc2' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite num banco reto segurando a barra acima do peito, pegada na largura dos ombros e braços levemente flexionados.', 'Inspirando, desça a barra num arco atrás da cabeça, mantendo o ângulo dos braços, até sentir o peito alongar.', 'Volte pelo mesmo arco, expirando.', 'Segure um segundo e repita.'] where id = '83d2526f-de44-46d4-b8b0-8e61d19d84dc' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite atravessado num banco reto, só com os ombros apoiados, quadril abaixo do banco e pés firmes.', 'Segure um halter (de anilhas bem presas) com as duas mãos acima do peito, braços levemente flexionados.', 'Inspirando, desça o halter num arco atrás da cabeça até sentir o peito alongar.', 'Volte pelo mesmo arco, expirando.'] where id = 'bee8aa91-7984-40be-a3ae-d8376d36b27d' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente no banco de desenvolvimento com a barra na altura dos ombros, pegada pronada mais aberta que os ombros.', 'Eleve a barra acima da cabeça.', 'Desça-a devagar atrás da cabeça, inspirando, e suba de novo.', 'Desça à frente, inspirando; isso é uma repetição. Alterne assim.'] where id = 'b9666710-f4ed-4bba-817e-4cf8e766c393' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Com a barra no rack na altura dos ombros, segure-a com pegada pronada e apoie na frente dos ombros.', 'Estenda os cotovelos e passe a barra para trás da cabeça, sem travar os cotovelos.', 'Desça atrás da cabeça até os cotovelos formarem 90° e suba de novo.', 'Desça à frente e alterne até completar as repetições.'] where id = 'cb0d82d8-6611-44e2-9263-ecd96134b41c' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique em pé sobre uma perna, com o outro joelho elevado.', 'Com um contramovimento, salte estendendo quadril, joelho e tornozelo da perna de apoio.', 'No ar, flexione o joelho tentando tocar o glúteo com o calcanhar da perna que saltou.', 'Volte a perna sob o quadril e aterrisse; a outra perna fica na mesma posição.'] where id = 'd09c3a9d-fea0-4181-aa7f-da4078a468b4' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na cadeira abdutora, escolha a carga e segure as alças laterais.', 'Mantenha o tronco parado.', 'Expirando, afaste as pernas contra os apoios.', 'Sinta a contração por um segundo e volte devagar, inspirando.'] where id = '37a3f2c7-be1e-434f-af80-5c60e200fae8' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na cadeira adutora, escolha a carga e segure as alças laterais.', 'Mantenha o tronco parado e evite trancos.', 'Expirando, aproxime as pernas contra os apoios.', 'Sinta a contração por um segundo e volte devagar, inspirando.'] where id = 'ae55ada6-4c51-485b-9034-608e65d39509' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Ajuste o aparelho: apoio na parte baixa da canela e o eixo alinhado ao joelho.', 'Escolha uma carga adequada.', 'Com boa postura, estenda totalmente uma perna e pause no alto.', 'Volte sem deixar a carga parar, mantendo a tensão; complete e troque de perna.'] where id = '6d9b00c8-edb8-4c55-8d46-f4defd049a2a' and coalesce(cardinality(execution), 0) = 0;
