update public.exercises set execution = array['Em pé, pés na largura dos ombros e mãos na cintura.', 'Dê um passo à frente e desça até o joelho de trás quase tocar o chão, tronco ereto e joelho da frente sobre o pé.', 'Suba empurrando com o calcanhar da frente.', 'Traga o pé de trás à frente e repita com a outra perna, avançando.'] where id = 'b09d5ad1-aa79-4ff6-a95b-b716bce05e66' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, pés na largura dos ombros, com a barra sobre a parte alta das costas.', 'Dê um passo à frente e desça até o joelho de trás quase tocar o chão, tronco ereto.', 'Suba empurrando com o calcanhar da frente.', 'Traga o pé de trás à frente e repita com a outra perna, avançando.'] where id = '5a5c966f-b0a5-4d39-89a2-8d0de1333997' and coalesce(cardinality(execution), 0) = 0;
