update public.exercises set execution = array['Em pé, segure uma anilha com as duas mãos nas posições de 3 e 9 horas, braços estendidos à frente.', 'Gire a anilha o máximo possível para um lado, como quem vira um volante.', 'Inverta e gire até o lado oposto.', 'Repita.'] where id = 'e742e074-be39-4795-994f-d9016fa21ae8' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Centralize-se entre as alças do aparelho, pés na largura do quadril.', 'Flexione o quadril para segurar as alças, inspire fundo e desça o quadril.', 'Com o peito erguido e as costas arqueadas, suba empurrando com os calcanhares, levando o quadril à frente.', 'Desça o peso flexionando o quadril e guiando-o até o chão.'] where id = '17eff180-8970-474d-919f-189164fd511f' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Pés a poucos centímetros um do outro, braço esquerdo erguido em posição atlética.', 'Com o pé direito, dê um passo rápido por trás e eleve o joelho.', 'Balance os braços acompanhando o joelho, que sobe e desce reto.', 'Desloque-se de lado sem girar os pés, olhando sempre à frente.'] where id = '1c8013e2-61cf-4fe0-bf17-56c53fc3f2a0' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique de quatro apoios no chão.', 'Puxe o umbigo para dentro e arredonde a coluna, a lombar, os ombros e o pescoço.', 'Deixe a cabeça cair.', 'Segure 15 segundos.'] where id = '7b9672fd-ab53-45cf-af4d-25f4f480b2b2' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Fique de frente para uma parede ou um parceiro.', 'Leve a bola atrás da cabeça com as duas mãos, alongando bem.', 'Arremesse com força para frente, acompanhando o movimento.', 'Prepare-se para receber o rebote; contra a parede, mire um pouco mais alto.'] where id = 'df4f9d26-3f59-4838-b228-cefa84a0410d' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda o meio de correntes a duas alças de cabo e deite num banco reto.', 'Comece com os cotovelos apontados para cima e os punhos pronados.', 'Estenda os cotovelos sem mexer os braços.', 'Pause no alto e volte à posição inicial.'] where id = 'a94274d1-d20e-47fa-bcd4-0af4cf2c4d37' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda as correntes às alças de cabo e deite num banco reto como num supino com halteres.', 'Comece com os braços perpendiculares ao chão e os punhos pronados.', 'Desça flexionando os cotovelos até 90°, deixando parte da corrente no chão.', 'Empurre de volta estendendo os cotovelos.'] where id = 'bcdf7553-f867-4c16-a775-9623f9b8ba53' and coalesce(cardinality(execution), 0) = 0;
