update public.exercises set execution = array['Sente no chão.', 'Coloque as mãos atrás da cabeça, dedos entrelaçados e cotovelos para frente.', 'Puxe a cabeça devagar em direção ao peito.', 'Segure 20 a 30 segundos.'] where id = '5379f2c6-62ca-47f7-9434-ec117982f62a' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Segure a barra fixa com pegada aberta, palmas para frente, e incline o tronco uns 30° para trás.', 'Expirando, suba inclinando-se para a esquerda até a barra quase tocar o peito, sem balançar.', 'Desça inspirando.', 'Suba agora inclinando-se para a direita e alterne os lados.'] where id = '2911af6f-2d2e-44ef-bb97-e5c4e9819143' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Comece com o halter gigante entre os pés, segurando a pegada grossa com as duas mãos.', 'Leve-o ao ombro estendendo quadril e joelhos, soltando a mão extra; deixe uma das cabeças atrás do ombro.', 'Flexione os joelhos e empurre o halter para o alto, inclinando-se levemente para o lado oposto.', 'Desça-o com controle até o chão, de preferência sobre um tapete grosso.'] where id = '067823df-e0a4-4143-b1dd-a5392961a972' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Barra no chão junto às canelas, pegada pronada logo fora das pernas, costas retas e peito erguido.', 'Estenda os joelhos mantendo o ângulo das costas e os braços retos até passar dos joelhos.', 'No meio das coxas, acelere estendendo quadril, joelhos e tornozelos; encolha os ombros e puxe-se para baixo da barra.', 'Receba a barra nos ombros num agachamento frontal e fique em pé empurrando com os calcanhares.'] where id = 'bb60f04f-a921-4ac2-8b2c-9c021e771d3d' and coalesce(cardinality(execution), 0) = 0;
