update public.exercises set execution = array['Pés um pouco além dos ombros; agache e segure a barra com pegada pronada um pouco além dos ombros, barra a 2–3 cm das canelas.', 'Costas retas, peito aberto, cabeça neutra; tire a barra do chão estendendo quadril e joelhos, sem subir o quadril antes dos ombros.', 'Após os joelhos, estenda quadril e joelhos com força e suba na ponta dos pés; encolha os ombros com os braços retos.', 'Puxe-se para baixo da barra e receba-a sobre as clavículas num quarto de agachamento; fique em pé e desça a barra com controle.'] where id = '4741454a-0e11-4454-b7cc-853d1026b2ef' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Barra sobre blocos na altura desejada, pegada logo fora das pernas.', 'Quadril baixo, peso nos calcanhares, costas retas e peito erguido.', 'No meio das coxas, acelere estendendo quadril, joelhos e tornozelos; encolha os ombros e puxe-se sob a barra.', 'Receba-a nos ombros, fique em pé e devolva aos blocos.'] where id = '3330e7eb-8dc1-4db7-84fa-542fb5a84767' and coalesce(cardinality(execution), 0) = 0;
