update public.exercises set execution = array['Pendure-se na barra fixa com pegada pronada um pouco além dos ombros, pernas juntas.', 'Flexione os joelhos a 90° com as coxas paralelas ao chão.', 'Expirando, eleve as pernas até as canelas quase tocarem a barra, estendendo-as o máximo possível no alto.', 'Desça o mais devagar possível, sem balançar.'] where id = 'a54e4f9c-e006-4c09-8518-68a5e38e7a75' and coalesce(cardinality(execution), 0) = 0;
