update public.exercises set execution = array['Em pé, joelhos levemente flexionados, mãos à frente do peito com as palmas para baixo.', 'Desça rápido num quarto de agachamento e exploda para cima.', 'Leve os joelhos ao peito tentando tocar as palmas.', 'Aterrisse estendendo as pernas e amorteça flexionando os joelhos.'] where id = '4a14030c-a2ba-4a5a-abeb-fef5ad7de0b4' and coalesce(cardinality(execution), 0) = 0;
