update public.exercises set execution = array['Segure uma ponta da corda em cada mão, com a corda no chão atrás de você.', 'Gire a corda por cima da cabeça até a frente.', 'Salte por cima quando ela chegar ao chão.', 'Mantenha um ritmo que consiga sustentar; varie velocidade e técnica.'] where id = 'b782dc48-8e1f-43cf-9eb2-04f3afa2e9c7' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Coloque os barris a uns 10–15 metros da plataforma.', 'Segure a alça próxima do primeiro barril, incline-o e pegue a borda de baixo do outro lado.', 'Leve o barril ao peito e caminhe rápido até a plataforma, segurando firme.', 'Suba-o estendendo quadril, joelhos e tornozelos; volte para o próximo.'] where id = '73b187fb-f83b-4a55-be7b-3a74da6e3b21' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Segure as argolas com a pegada falsa (base das palmas sobre as argolas).', 'Balance as pernas um pouco para trás e depois com força para frente e para cima, puxando-se com os braços.', 'No alto da puxada, traga as argolas às axilas girando os ombros à frente.', 'Estenda os cotovelos para completar a subida; desça com cuidado.'] where id = '54e55f9e-8bba-4273-bce8-ac08d4ce4a2d' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Prenda uma ponta da barra num landmine ou num canto e coloque a carga.', 'Leve a outra ponta à altura dos ombros com os braços estendidos, base aberta.', 'Gire tronco e quadril, levando a carga até embaixo de um lado.', 'Inverta e leve-a até o lado oposto, alternando, braços sempre estendidos.'] where id = '386f5a4e-cd63-4dc6-85e7-cebc4ab07b6e' and coalesce(cardinality(execution), 0) = 0;
