update public.exercises set execution = array['Em pé, pés um pouco além do quadril e joelhos levemente flexionados.', 'Mão direita no quadril direito.', 'Eleve o braço esquerdo e leve a mão atrás da cabeça.', 'Incline o tronco para a direita com o peso igual nas duas pernas; troque de lado.'] where id = '3a45575c-0353-4a35-9282-a72b5399b0d6' and coalesce(cardinality(execution), 0) = 0;
