update public.exercises set execution = array['Fique ao lado de um cone, apoiado numa perna com o joelho levemente flexionado.', 'Salte de lado por cima do cone.', 'Aterrisse na mesma perna.', 'Salte de volta na hora e continue indo e voltando.'] where id = '03c4e08c-1df0-4d4d-835b-a5f55099df30' and coalesce(cardinality(execution), 0) = 0;
