update public.exercises set execution = array['Sente no leg press com os pés bem próximos (até uns 8 cm) no centro da plataforma, pontas levemente para fora.', 'Destrave a plataforma e estenda as pernas sem travar os joelhos.', 'Inspirando, desça até os joelhos formarem 90°.', 'Suba empurrando com os calcanhares; ao terminar, trave bem a plataforma.'] where id = '11faaa90-52af-42dd-8d57-2a60e974c654' and coalesce(cardinality(execution), 0) = 0;
