update public.exercises set execution = array['Passe os elásticos curtos pela barra e pise neles (os longos vão presos a uma base firme).', 'Segure a barra na largura dos ombros.', 'Inspire fundo, desça o quadril até as canelas tocarem a barra, peito erguido, e suba empurrando com os calcanhares.', 'Após os joelhos, leve o quadril à barra; desça guiando a barra até o chão.'] where id = '45930a91-7aeb-43b8-8dee-702f150c3b14' and coalesce(cardinality(execution), 0) = 0;
