update public.exercises set execution = array['Com a barra apoiada na frente dos ombros, pés sob o quadril.', 'Flexione um pouco os joelhos, sem levar o quadril para trás, e inverta com o máximo de força.', 'Afaste um pouco os pés e receba a barra com os braços travados acima da cabeça, joelhos parcialmente flexionados.', 'Fique em pé.'] where id = '40dd1dd6-529e-4484-a254-e615a2c26e91' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, um halter em cada mão ao lado do corpo, palmas para o tronco, pés na largura dos ombros.', 'Com os braços retos e o tronco parado, eleve os halteres para os lados até a altura dos ombros, expirando.', 'Mantenha as palmas para baixo com o mindinho um pouco mais alto.', 'Segure um segundo e desça devagar.'] where id = '6398376f-f479-4046-82f3-7c0f3fbca48f' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Use um implemento (ou pneu/caixa) e degraus de uns 40–45 cm.', 'Segure o implemento com as duas mãos, pés afastados, cabeça e peito erguidos.', 'Levante-o empurrando com os calcanhares e balance-o para cima do degrau, ajudando com as pernas.', 'Repita 3 a 5 vezes, depois aumente a carga, o mais rápido possível.'] where id = 'f9cb3dd2-628b-4c64-b255-882dfff74c1e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Apoie os braços no banco Scott segurando um halter em cada mão, palmas frente a frente.', 'Inspirando, desça até estender o braço e alongar o bíceps.', 'Expirando, flexione até o bíceps contrair e os halteres chegarem à altura dos ombros.', 'Segure um segundo e repita.'] where id = 'd5a80892-1999-426c-9ae4-36e4a47e7692' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite no banco de abdominal com as pernas presas e uma barra sobre o peito.', 'Inspirando, contraia abdômen e glúteos.', 'Expirando, suba o tronco como num abdominal enquanto empurra a barra acima da cabeça.', 'Desça o tronco trazendo a barra de volta ao peito, inspirando.'] where id = 'd4f72dbb-454c-44ef-a828-a7360501f4dd' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite num banco reto segurando um halter com o braço estendido, perpendicular ao corpo, palma voltada para os pés.', 'Apoie a outra mão no bíceps do braço que trabalha.', 'Inspirando, desça o halter devagar.', 'Expirando, estenda de volta contraindo o tríceps; troque de braço.'] where id = '54bc86f2-69ed-4d41-bd3a-169f3baf4e7e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite de bruços num banco reto com um halter numa mão e a cabeça apoiada no outro braço.', 'Braço paralelo ao chão, a 90° do tronco, e cotovelo a 90° com o antebraço apontando para o chão.', 'Expirando, gire o antebraço para frente até ficar paralelo ao chão, mantendo os 90°.', 'Segure um segundo e volte devagar.'] where id = 'a5ad05a4-e98f-45d7-a29d-26642eee0c31' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Coloque carga no trenó (o suficiente para exigir esforço sem deixá-lo lento demais).', 'Segure as alças altas ou baixas com os braços estendidos, inclinado contra ele.', 'Empurre com passos curtos e alternados, boa postura.', 'Vá o mais rápido possível por uma distância curta.'] where id = '6762a2aa-ccc1-4e29-bc43-693ec26f2c00' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na puxada com a barra larga e ajuste o apoio dos joelhos.', 'Segure a barra com pegada supinada, mãos mais fechadas que os ombros, e incline o tronco uns 30° para trás.', 'Expirando, puxe a barra até a parte alta do peito com os cotovelos junto ao corpo.', 'Contraia as costas por um segundo e volte devagar até estender os braços.'] where id = 'a838c7b1-e3be-468e-a227-888a7846727e' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Sente na remada baixa com os joelhos levemente flexionados e segure a alça com a mão esquerda, pegada pronada.', 'Com o braço estendido, endireite o tronco a 90° das pernas, peito aberto.', 'Expirando, puxe a alça até o abdômen girando o punho até a palma ficar voltada para o tronco.', 'Contraia as costas, volte devagar girando o punho de novo; troque de braço.'] where id = '869b7c10-e683-4cc1-85ba-24bd782af2f7' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Deite num banco declinado com as pernas presas e pegue a barra atrás da cabeça com pegada pronada mais aberta que os ombros.', 'Leve a barra até os braços ficarem estendidos e perpendiculares ao chão.', 'Inspirando, desça a barra num semicírculo até os braços ficarem paralelos ao chão, braços sempre estendidos.', 'Expirando, volte; no fim, desça a barra até a altura da cabeça e solte.'] where id = '2828651c-0717-42ba-88cf-628757a65a78' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, pés na largura dos ombros, eleve os braços para os lados até a altura dos ombros, palmas para baixo.', 'Mantenha o corpo parado.', 'Gire os punhos para frente em círculos, como se desenhasse com as mãos.', 'Respire normalmente e repita.'] where id = '6f0e2385-edd1-40a3-8276-4758e3911d14' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, cruze o braço esquerdo à frente do corpo e segure o punho esquerdo com a mão direita, na altura do quadril.', 'Comece com o braço esquerdo flexionado.', 'Estenda-o devagar, puxando e elevando até a altura do ombro.', 'Sinta nas costas, sem forçar o ombro; troque de lado.'] where id = '64886ba0-12ab-43b9-b99e-075e30d7f508' and coalesce(cardinality(execution), 0) = 0;
update public.exercises set execution = array['Em pé, segure o rolo de punho com pegada pronada e os braços estendidos à frente, paralelos ao chão.', 'Comece com a corda desenrolada.', 'Gire um punho de cada vez para cima, enrolando a corda até o peso chegar ao rolo.', 'Desça o peso devagar girando para o outro lado.'] where id = '43b9e336-75fa-4046-81a8-15f73bc679b8' and coalesce(cardinality(execution), 0) = 0;
