update public.exercises set execution = array['Com a barra apoiada atrás dos ombros, pés sob o quadril.', 'Flexione um pouco os joelhos, sem levar o quadril para trás, e inverta com força.', 'Use o impulso para empurrar a barra acima da cabeça estendendo os braços.', 'Volte à posição inicial absorvendo com as pernas.'] where id = '97c77e29-dc2e-4c87-bfc7-e8eb7214af5f' and coalesce(cardinality(execution), 0) = 0;
