update public.exercises set execution = array['Sente na puxada, ajuste o apoio dos joelhos e segure a barra com a pegada indicada (fechada, média ou aberta), palmas para frente.', 'Incline o tronco uns 30° para trás, peito aberto.', 'Expirando, puxe a barra até a parte alta do peito, levando ombros e braços para baixo e para trás.', 'Contraia as costas e volte devagar até estender os braços, inspirando.'] where id = 'b60ca544-5b3d-4056-8001-7d5664d78cc6' and coalesce(cardinality(execution), 0) = 0;
