update public.exercises set execution = array['Fique de costas para a polia baixa, a alguns passos, com o cabo entre as pernas afastadas.', 'Flexione o quadril levando as mãos por entre as pernas, joelhos levemente flexionados.', 'Com os braços retos, estenda o quadril até ficar em pé.', 'Não puxe com os ombros; o movimento vem do quadril.'] where id = 'd265eb21-752b-469b-882e-343804832b02' and coalesce(cardinality(execution), 0) = 0;
